const listUsersByRoles = `-- name: ListUsersByRoles :many
SELECT id, name, role FROM users WHERE role IN (/*SLICE:roles*/?) ORDER BY name
`

type ListUsersByRolesRow struct {
	ID   int64
	Name string
	Role string
}

func (q *Queries) ListUsersByRoles(ctx context.Context, roles []string) ([]ListUsersByRolesRow, error) {
	query := listUsersByRoles
	var queryParams []interface{}
	if len(roles) > 0 {
		for _, v := range roles {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:roles*/?", strings.Repeat(",?", len(roles))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:roles*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUsersByRolesRow
	for rows.Next() {
		var i ListUsersByRolesRow
		if err := rows.Scan(&i.ID, &i.Name, &i.Role); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

